// builder_c.s -- RNDP Replicator 3 (compact layout) builder, RV32EC.  Reads the layout data (lay_data.s, generated by tools/lay2asm.py from the
// placer/router output) and builds a copy of the machine through the arm: PLACE ROM and arm, PLACE every NAND/DFF site, PLACE the RAM, copy the ROM
// image (PROGRAM_ROM), then lay one routed path per sink (TRACK / VIA), ports last (EN is the last port), the RUN sinks after them, halt.
// All coordinates are relative to the parent's arm; the child's arm is at x = CHILD_DX.  NAND pins: A (x,y) B (x,y+1) Y (x+1,y); DFF pins: D (x,y) Q (x+1,y).
// Arm registers (a store into the window at ARM_BASE is one arm write): 0,1 A.x  2,3 A.y  4,5 B.x  6,7 B.y  8 KIND  9 ANGLE  10 VAL  15 CMD.
// CMD 1 PLACE, 3 PROGRAM_ROM, 4 TRACK (VAL = layer), 5 VIA.  Registers 11..14 are reserved (writing them is a fault): stores are sb/sh only.
// Registers: s0 = arm window; s1 = path stream pointer; sp = kind bitmap / port table pointer; a0,a1 = site x,y; a2 = kind byte, a3 = entries left;
// gp,tp = column,row counters.  dpath clobbers t0-t2, a4, a5 and RAM[LAYER]; RAM[KIND] holds the current site's kind.
.equ ARM,        ARM_BASE
.equ LAYER,      0x50                // RAM: layer of the path being laid
.equ KIND,       0x51                // RAM: kind of the site whose pins are being wired

start:                              // reset lands here (ROM_BASE)
    li   s0, ARM                    // arm window base
    // ---- the child's ROM and arm first (PROGRAM_ROM needs the ROM; nothing is wired before the image is copied)
    li   t0, CHILD_DX + ROM_X       // A.x = x of the child's ROM
    sh   t0, 0(s0)
    li   t0, ROM_Y
    sh   t0, 2(s0)
    li   t0, 2                      // KIND = ROM
    sb   t0, 8(s0)
    li   t0, ROM_ROT                // ANGLE
    sb   t0, 9(s0)
    li   t0, ROM_AB                 // VAL = ROM address bits
    sb   t0, 10(s0)
    li   t1, 1                      // constant 1 = PLACE
    sb   t1, 15(s0)                 // PLACE the ROM
    li   t0, CHILD_DX + ARM_X       // the child's arm
    sh   t0, 0(s0)
    li   t0, ARM_Y
    sh   t0, 2(s0)
    li   t0, 3                      // KIND = ARM
    sb   t0, 8(s0)
    li   t0, ARM_ROT
    sb   t0, 9(s0)
    sb   x0, 10(s0)                 // VAL = 0
    sb   t1, 15(s0)                 // PLACE the arm
    sb   x0, 9(s0)                  // ANGLE = 0 for NAND and DFF
    // ---- every NAND / DFF site (row-major; kind bitmap: 2 bits per site, 4 per byte, low bits first: 0 NAND 1 DFF 2 empty)
    li   sp, lay_kinds
    li   a3, 0                      // no kind entries buffered
    li   a1, GY0
    li   tp, ROWS
pl_row:
    li   a0, CHILD_DX + GX0
    li   gp, COLS
pl_col:
    bnez a3, pl_have
    lbu  a2, 0(sp)                  // next bitmap byte
    addi sp, sp, 1
    li   a3, 4
pl_have:
    andi t0, a2, 3                  // kind of this site
    srli a2, a2, 2
    addi a3, a3, -1
    li   t2, 2
    beq  t0, t2, pl_skip            // empty site
    sh   a0, 0(s0)                  // A.x
    sh   a1, 2(s0)                  // A.y
    sb   t0, 8(s0)                  // KIND = 0 NAND / 1 DFF
    sb   t1, 15(s0)                 // PLACE
pl_skip:
    addi a0, a0, PX
    addi gp, gp, -1
    bnez gp, pl_col
    addi a1, a1, PY
    addi tp, tp, -1
    bnez tp, pl_row
    // ---- the RAM part
    li   t0, CHILD_DX + RAM_X
    sh   t0, 0(s0)
    li   t0, RAM_Y
    sh   t0, 2(s0)
    li   t0, 4                      // KIND = RAM
    sb   t0, 8(s0)
    li   t0, RAM_ROT
    sb   t0, 9(s0)
    li   t0, RAM_AB                 // VAL = address width
    sb   t0, 10(s0)
    sb   t1, 15(s0)                 // PLACE the RAM
    sb   x0, 8(s0)                  // KIND, ANGLE, VAL back to 0
    sb   x0, 9(s0)
    sb   x0, 10(s0)
    // ---- program the child's ROM with this ROM's image (before anything is wired); zero bytes need no command
    li   t0, CHILD_DX + ROM_X
    sh   t0, 0(s0)                  // A = the child's ROM origin
    li   t0, ROM_Y
    sh   t0, 2(s0)
    li   s1, ROM_BASE               // read pointer
    li   a2, 0                      // ROM offset
    li   a3, 3                      // CMD = PROGRAM_ROM
    li   a4, lay_end                // end of the image
rom_loop:
    lbu  t0, 0(s1)
    beqz t0, rom_skip               // nothing to program
    sh   a2, 4(s0)                  // B.x = offset
    sb   t0, 10(s0)                 // VAL = byte
    sb   a3, 15(s0)                 // PROGRAM_ROM
rom_skip:
    addi s1, s1, 1
    addi a2, a2, 1
    bne  s1, a4, rom_loop
    // ---- the paths of all node pins: sites in the same order as above, pin A then B (a DFF has only D)
    li   s1, lay_paths
    li   sp, lay_kinds
    li   a3, 0
    li   a1, GY0
    li   tp, ROWS
wr_row:
    li   a0, CHILD_DX + GX0
    li   gp, COLS
wr_col:
    bnez a3, wr_have
    lbu  a2, 0(sp)
    addi sp, sp, 1
    li   a3, 4
wr_have:
    andi t0, a2, 3
    srli a2, a2, 2
    addi a3, a3, -1
    li   t2, 2
    beq  t0, t2, wr_skip            // empty site: no pins
    sb   t0, KIND(x0)               // remember NAND / DFF across the call
    mv   a4, a0                     // pin A at (x, y)
    mv   a5, a1
    jal  ra, dpath
    lbu  t0, KIND(x0)
    bnez t0, wr_skip                // DFF: one pin only
    addi a5, a1, 1                  // pin B at (x, y+1)
    mv   a4, a0
    jal  ra, dpath
wr_skip:
    addi a0, a0, PX
    addi gp, gp, -1
    bnez gp, wr_col
    addi a1, a1, PY
    addi tp, tp, -1
    bnez tp, wr_row
    // ---- ports (EN last), start cells from the table
    li   sp, lay_port_starts
    li   gp, NPORTS
pt_loop:
    lh   a4, 0(sp)
    lh   a5, 2(sp)
    addi sp, sp, 4
    jal  ra, dpath
    addi gp, gp, -1
    bnez gp, pt_loop
    // ---- RUN sinks last
    li   sp, lay_run_starts
    li   gp, NRUN
run_loop:
    beqz gp, halt
    lh   a4, 0(sp)
    lh   a5, 2(sp)
    addi sp, sp, 4
    jal  ra, dpath
    addi gp, gp, -1
    j    run_loop
halt:                               // finished: the child is built; the model's halt convention
    j    halt

// ---- dpath: lay the path whose first segment starts at (a4,a5), reading segment bytes at s1.  Segment byte: [7] last [6] via [5:4] dir [3:0] length
// (length 0: the next byte is the length; a length byte of 0 means no path).  The first segment's via bit = start on layer 1; later via bits: VIA at the
// current point, then the layer toggles.
dpath:
    lbu  t0, 0(s1)
    addi s1, s1, 1
    andi t1, t0, 15
    bnez t1, dp_len
    lbu  t1, 0(s1)                  // extended length
    addi s1, s1, 1
    bnez t1, dp_len
    ret                             // 0: no path
dp_len:
    srli t2, t0, 6                  // first segment: via bit = start layer
    andi t2, t2, 1
    sb   t2, LAYER(x0)
    sb   t2, 10(s0)                 // VAL = layer
    j    dp_seg
dp_next:
    lbu  t0, 0(s1)
    addi s1, s1, 1
    andi t1, t0, 15
    bnez t1, dp_nl
    lbu  t1, 0(s1)
    addi s1, s1, 1
dp_nl:
    andi t2, t0, 0x40
    beqz t2, dp_seg
    sh   a4, 0(s0)                  // VIA at the current point
    sh   a5, 2(s0)
    li   t2, 5
    sb   t2, 15(s0)
    lbu  t2, LAYER(x0)
    xori t2, t2, 1
    sb   t2, LAYER(x0)
    sb   t2, 10(s0)
dp_seg:                             // t0 = segment byte, t1 = length
    sh   a4, 0(s0)                  // A = current point
    sh   a5, 2(s0)
    srli t2, t0, 4
    andi t2, t2, 3                  // direction
    beqz t2, dp_r
    addi t2, t2, -1
    beqz t2, dp_l
    addi t2, t2, -1
    beqz t2, dp_d
    sub  a5, a5, t1                 // 3: -y
    j    dp_emit
dp_r:
    add  a4, a4, t1                 // 0: +x
    j    dp_emit
dp_l:
    sub  a4, a4, t1                 // 1: -x
    j    dp_emit
dp_d:
    add  a5, a5, t1                 // 2: +y
dp_emit:
    sh   a4, 4(s0)                  // B = new point
    sh   a5, 6(s0)
    li   t2, 4                      // TRACK
    sb   t2, 15(s0)
    andi t2, t0, 0x80
    beqz t2, dp_next                // not the last segment
    ret
